import React, { useEffect, useState } from 'react';
import { AnimatedSprite, useApp } from '@inlet/react-pixi';
import * as PIXI from 'pixi.js';

const animations = {
  idle: { file: 'Cat-3-Idle.png', frames: 10 },
  sitting: { file: 'Cat-3-Sitting.png', frames: 1 },
  walk: { file: 'Cat-3-Walk.png', frames: 8 },
  run: { file: 'Cat-3-Run.png', frames: 8 },
  meow: { file: 'Cat-3-Meow.png', frames: 5 },
  licking1: { file: 'Cat-3-Licking-1.png', frames: 5 },
  stretching: { file: 'Cat-3-Stretching.png', frames: 5 }
};

export default function Cat({ action = 'idle', x = 0, y = 0, flip = false }) {
  const app = useApp();
  const [textures, setTextures] = useState([]);
  const [spriteSize, setSpriteSize] = useState({ width: 50, height: 50 });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const loadedTextures = {};
    let allLoaded = 0;
    const totalToLoad = Object.keys(animations).length;

    Object.entries(animations).forEach(([key, { file, frames }]) => {
      const path = `${process.env.PUBLIC_URL}/sprites/${file}`;
      const baseTexture = PIXI.BaseTexture.from(path);

      baseTexture.on('loaded', () => {
        const frameWidth = baseTexture.width / frames;
        const frameHeight = baseTexture.height;

        if (!loaded) {
          setSpriteSize({ width: frameWidth, height: frameHeight });
        }

        loadedTextures[key] = Array.from({ length: frames }, (_, i) =>
          new PIXI.Texture(baseTexture, new PIXI.Rectangle(i * frameWidth, 0, frameWidth, frameHeight))
        );

        allLoaded++;
        if (allLoaded === totalToLoad) {
          setLoaded(true);
        }
      });

      baseTexture.on('error', (err) => {
        console.error(`Error cargando textura ${file}:`, err);
      });
    });

    return () => {
      Object.values(loadedTextures).forEach(textureArray => {
        textureArray.forEach(texture => {
          if (texture && texture.baseTexture) {
            texture.baseTexture.destroy();
          }
        });
      });
    };
  }, []);

  useEffect(() => {
    if (loaded && animations[action]) {
      const { file, frames } = animations[action];
      const path = `${process.env.PUBLIC_URL}/sprites/${file}`;
      const baseTexture = PIXI.BaseTexture.from(path);

      const frameWidth = baseTexture.width / frames;
      const frameHeight = baseTexture.height;

      const actionTextures = Array.from({ length: frames }, (_, i) =>
        new PIXI.Texture(baseTexture, new PIXI.Rectangle(i * frameWidth, 0, frameWidth, frameHeight))
      );

      setTextures(actionTextures);
    }
  }, [action, loaded]);

  if (!textures.length) return null;

  return (
    <AnimatedSprite
      textures={textures}
      isPlaying={true}
      animationSpeed={0.2}
      width={spriteSize.width}
      height={spriteSize.height}
      x={x}
      y={y}
      anchor={0.5}
      scale={{ x: flip ? -1 : 1, y: 1 }}
    />
  );
}
